package piglatin

import "strings"

// Sentence translates an English sentence into Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = pig(word)
	}
	return strings.Join(words, " ")
}

func pig(word string) string {
	// Rule 1: words starting with a vowel, "xr", or "yt" just get "ay" appended.
	if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return word + "ay"
	}

	// Find where the leading consonant cluster ends.
	i := 0
	for i < len(word) {
		c := word[i]
		// Rule 3: a "qu" (possibly after consonants) moves with the cluster.
		if c == 'q' && i+1 < len(word) && word[i+1] == 'u' {
			i += 2
			break
		}
		// Rules 2 and 4: the cluster ends at the first vowel, or at a
		// "y" that comes after at least one consonant.
		if isVowel(c) || (c == 'y' && i > 0) {
			break
		}
		i++
	}

	return word[i:] + word[:i] + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}
